function validate([costs, k, candidates]) {
  const n = costs.length;
  if (n < 1 || n > 100000) return 'costs needs 1 to 100000 values.';
  if (costs.some(c => !Number.isInteger(c) || c < 1 || c > 100000)) return 'Each cost is an integer from 1 to 10^5.';
  if (!Number.isInteger(k) || k < 1 || k > n) return 'k is an integer from 1 to costs.length.';
  if (!Number.isInteger(candidates) || candidates < 1 || candidates > n) return 'candidates is an integer from 1 to costs.length.';
  return null;
}

