function totalCost(costs, k, candidates) {
  const heap = [];
  const before = (a, b) => costs[a] < costs[b] || (costs[a] === costs[b] && a < b);
  const swap = (i, j) => { [heap[i], heap[j]] = [heap[j], heap[i]]; };
  const push = (worker) => {
    heap.push(worker);
    let child = heap.length - 1;
    while (child > 0 && before(heap[child], heap[(child - 1) >> 1])) {
      swap(child, (child - 1) >> 1);
      child = (child - 1) >> 1;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let parent = 0;
    for (;;) {
      let smallest = parent;
      for (const child of [2 * parent + 1, 2 * parent + 2]) {
        if (child < heap.length && before(heap[child], heap[smallest])) smallest = child;
      }
      if (smallest === parent) return top;
      swap(parent, smallest);
      parent = smallest;
    }
  };

  let left = 0;
  let right = costs.length - 1;
  for (let i = 0; i < candidates && left <= right; i++) push(left++);
  for (let i = 0; i < candidates && left <= right; i++) push(right--);

  let total = 0;
  for (let hired = 0; hired < k; hired++) {
    const worker = pop();
    total += costs[worker];
    if (left <= right) {
      if (worker < left) {
        push(left++);
      } else {
        push(right--);
      }
    }
  }
  return total;
}

