function totalCost(costs, k, candidates) {
  const line = costs.map((cost, index) => ({ cost, index }));
  let sum = 0;
  for (let round = 0; round < k; round++) {
    let pickAt = -1;
    for (let p = 0; p < line.length; p++) {
      if (p >= candidates && p < line.length - candidates) continue;
      if (pickAt < 0 || line[p].cost < line[pickAt].cost || (line[p].cost === line[pickAt].cost && line[p].index < line[pickAt].index)) pickAt = p;
    }
    sum += line[pickAt].cost;
    line.splice(pickAt, 1);
  }
  return sum;
}

