function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 2000 : pick(1, 10);
  const top = size === 'large' ? [5, 1000, 100000][pick(0, 2)] : pick(1, 6);
  const costs = Array.from({ length: n }, () => pick(1, top));
  const k = pick(1, n);
  const candidates = rand() < 0.5 ? pick(1, Math.max(1, Math.floor(n / 10))) : pick(1, n);
  return [costs, k, candidates];
}
